func clonePublishResult(result ConfigPublishResult) ConfigPublishResult {
	result.Content = cloneJSON(result.Content)
	return result
}

func cloneJSON(raw json.RawMessage) json.RawMessage {
	if raw == nil {
		return nil
	}
	return append(json.RawMessage(nil), raw...)
}

// isNonEmptyJSONObject reports whether raw is exactly one JSON object with at
// least one member. It is shared by HTTP validation and WAL recovery. Numbers
// stay json.Number literals (via decodeJSONValue) so legal values beyond the
// float64 range, such as 1e309 or 1e-400, validate and survive recovery
// instead of being rejected as unrepresentable floats.
func isNonEmptyJSONObject(raw json.RawMessage) bool {
	value, ok := decodeJSONValue(raw)
	if !ok {
		return false
	}
	object, ok := value.(map[string]any)
	return ok && len(object) > 0
}

// sameJSON compares two JSON documents semantically: object key order and
// insignificant whitespace are ignored, numbers compare by their exact
// written decimal value, and array element order is significant.
func sameJSON(a, b json.RawMessage) bool {
	av, aok := decodeJSONValue(a)
	bv, bok := decodeJSONValue(b)
	if !aok || !bok {
		return false
	}
	return jsonValueEqual(av, bv)
}

// decodeJSONValue decodes exactly one JSON document, keeping numbers as their
// original literal (json.Number) so no precision is lost before comparison.
func decodeJSONValue(raw json.RawMessage) (any, bool) {
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return nil, false
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		return nil, false
	}
	return value, true
}

func jsonValueEqual(a, b any) bool {
	switch av := a.(type) {
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for key, value := range av {
			other, ok := bv[key]
			if !ok || !jsonValueEqual(value, other) {
				return false
			}
		}
		return true
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !jsonValueEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case json.Number:
		// Numbers compare by exact decimal value: 1, 1.0 and 1e0 are equal,
		// but 9007199254740992 and 9007199254740993 (or 0 and 1e-400) are
		// not, even though each pair shares one float64.
		bv, ok := b.(json.Number)
		return ok && sameJSONNumber(av, bv)
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case nil:
		return b == nil
	default:
		return false
	}
}

// sameJSONNumber reports whether two JSON number literals denote the same
// exact decimal value. Parsing through big.Rat keeps every written digit and
// exponent significant, so neither large integers beyond 2^53 nor tiny
// numbers that would underflow to zero are ever conflated.
func sameJSONNumber(a, b json.Number) bool {
	ra, okA := new(big.Rat).SetString(a.String())
	rb, okB := new(big.Rat).SetString(b.String())
	if !okA || !okB {
		// A literal the exact parser rejects (never produced by the JSON
		// decoder) falls back to comparing the written form.
		return a.String() == b.String()
	}
	return ra.Cmp(rb) == 0
}

package fleet

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"testing"
	"time"
)

// --- response types and helpers ---------------------------------------------

type taskResponse struct {
	ID              int64           `json:"id"`
	RequestID       string          `json:"requestId"`
	DurationSeconds int             `json:"durationSeconds"`
	Status          string          `json:"status"`
	Attempts        int             `json:"attempts"`
	CreatedAt       time.Time       `json:"createdAt"`
	NextClaimableAt time.Time       `json:"nextClaimableAt"`
	ClaimedAt       *time.Time      `json:"claimedAt"`
	Deadline        *time.Time      `json:"deadline"`
	Result          json.RawMessage `json:"result"`
	FailureReason   string          `json:"failureReason"`
	CompletedAt     *time.Time      `json:"completedAt"`
}

type claimResponse struct {
	Task       taskResponse `json:"task"`
	Attempt    int          `json:"attempt"`
	Credential string       `json:"credential"`
	Deadline   time.Time    `json:"deadline"`
}

type taskReportResponse struct {
	ReceiptID  string          `json:"receiptId"`
	Success    bool            `json:"success"`
	Reason     string          `json:"reason"`
	Result     json.RawMessage `json:"result"`
	ReceivedAt time.Time       `json:"receivedAt"`
}

type taskAuditResponse struct {
	Seq        int64     `json:"seq"`
	Event      string    `json:"event"`
	FromStatus string    `json:"fromStatus"`
	ToStatus   string    `json:"toStatus"`
	Attempt    int       `json:"attempt"`
	At         time.Time `json:"at"`
	Reason     string    `json:"reason"`
}

func taskBody(requestID string, seconds int) string {
	return fmt.Sprintf(`{"requestId":%q,"durationSeconds":%d}`, requestID, seconds)
}

func reportBody(receiptID, credential string, success bool, reason, result string) string {
	if success {
		return fmt.Sprintf(`{"receiptId":%q,"credential":%q,"success":true,"result":%s}`, receiptID, credential, result)
	}
	return fmt.Sprintf(`{"receiptId":%q,"credential":%q,"success":false,"reason":%q}`, receiptID, credential, reason)
}

func createTask(t *testing.T, h http.Handler, device, body string, wantStatus int) taskResponse {
	t.Helper()
	r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks", device), body)
	if r.Code != wantStatus {
		t.Fatalf("create task status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
	}
	if wantStatus == http.StatusCreated || wantStatus == http.StatusOK {
		return decodeBody[taskResponse](t, r)
	}
	return taskResponse{}
}

func claimTask(t *testing.T, h http.Handler, device string, wantStatus int) claimResponse {
	t.Helper()
	r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks/claim", device), "")
	if r.Code != wantStatus {
		t.Fatalf("claim status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
	}
	if wantStatus == http.StatusOK {
		return decodeBody[claimResponse](t, r)
	}
	return claimResponse{}
}

func reportTask(t *testing.T, h http.Handler, device string, taskID int64, body string, wantStatus int) taskReportResponse {
	t.Helper()
	r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks/%d/reports", device, taskID), body)
	if r.Code != wantStatus {
		t.Fatalf("report status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
	}
	if wantStatus == http.StatusCreated || wantStatus == http.StatusOK {
		return decodeBody[taskReportResponse](t, r)
	}
	return taskReportResponse{}
}

func getTask(t *testing.T, h http.Handler, device string, taskID int64, wantStatus int) taskResponse {
	t.Helper()
	r := doRequest(t, h, http.MethodGet, fmt.Sprintf("/v1/devices/%s/tasks/%d", device, taskID), "")
