385	// A cancel of an in-progress task whose cancel record cannot be persisted
386	// returns 503 and changes nothing: the task keeps executing under the same
387	// claim (attempt count, claim time, deadline and credential), gains no
388	// completion time, result or canceled audit record, and the device stays
389	// occupied so the next claim keeps returning 204 without advancing the
390	// pending task. The detail and list views report the same un-canceled state.
391	func TestPersistentTaskCancelWriteFailureKeepsExecution(t *testing.T) {
392		dir := t.TempDir()
393		store := openPersistent(t, dir)
394		h := NewHandler(store)
395		mustRegister(t, h, "gw")
396	
397		// Task 1 is claimed and stays within its deadline; task 2 waits pending.
398		createTask(t, h, "gw", taskBody("req-1", 30), http.StatusCreated)
399		claim := claimTask(t, h, "gw", http.StatusOK)
400		if claim.Task.ID != 1 {
401			t.Fatalf("first claim took task %d, want 1", claim.Task.ID)
402		}
403		createTask(t, h, "gw", taskBody("req-2", 30), http.StatusCreated)
404		claimedAt := claim.Task.ClaimedAt
405		deadline := claim.Deadline
406	
407		// Fail the cancel write (one unacknowledged append, as in a disk outage).
408		real := store.wal.(*walFile)
409		store.wal = &failingWAL{inner: real}
410		r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/tasks/1/cancel", "")
411		if r.Code != http.StatusServiceUnavailable {
412			t.Fatalf("failing cancel = %d, want 503: %s", r.Code, r.Body.String())
413		}
414	
415		// The task is still the same in-progress execution.
416		task := getTask(t, h, "gw", 1, http.StatusOK)
417		if task.Status != "in_progress" {
418			t.Fatalf("failed cancel changed status to %q, want in_progress", task.Status)
419		}
420		if task.Attempts != 1 {
421			t.Fatalf("failed cancel changed attempts to %d, want 1", task.Attempts)
422		}
423		if task.ClaimedAt == nil || !task.ClaimedAt.Equal(*claimedAt) {
424			t.Fatalf("failed cancel changed claimedAt: %+v, want %s", task.ClaimedAt, claimedAt)
425		}
426		if task.Deadline == nil || !task.Deadline.Equal(deadline) {
427			t.Fatalf("failed cancel changed deadline: %+v, want %s", task.Deadline, deadline)
428		}
429		if task.CompletedAt != nil {
430			t.Fatalf("failed cancel set completedAt: %s", task.CompletedAt)
431		}
432		if len(task.Result) != 0 || task.FailureReason != "" {
433			t.Fatalf("failed cancel produced an outcome: result=%s reason=%q", task.Result, task.FailureReason)
434		}
435		// The execution credential is still bound to the attempt.
436		if ts := store.devices["gw"].tasks[0]; ts.task.Credential != claim.Credential {
437			t.Fatalf("failed cancel revoked credential %q, want %q", ts.task.Credential, claim.Credential)
438		}
439	
440		// The audit trail keeps exactly the pre-cancel records, with no canceled event.
441		if got := joinEvents(eventsOf(listAudit(t, h, "gw", 1))); got != "created,claimed" {
442			t.Fatalf("task 1 audit after failed cancel = %s, want created,claimed", got)
443		}
444	
445		// The device is still occupied by task 1: another claim is 204 and the
446		// pending task is not pulled forward.
447		claimTask(t, h, "gw", http.StatusNoContent)
448		task2 := getTask(t, h, "gw", 2, http.StatusOK)
449		if task2.Status != "pending" || task2.Attempts != 0 || task2.ClaimedAt != nil {
450			t.Fatalf("pending task advanced despite occupied device: %+v", task2)
451		}
452		if got := joinEvents(eventsOf(listAudit(t, h, "gw", 2))); got != "created" {
453			t.Fatalf("task 2 audit = %s, want created", got)
454		}
455	
456		// The list view reflects the same state, not just the cancel error code.
457		list := decodeBody[struct {
458			Tasks []taskResponse `json:"tasks"`
459		}](t, doRequest(t, h, http.MethodGet, "/v1/devices/gw/tasks", ""))
460		if len(list.Tasks) != 2 {
461			t.Fatalf("task list has %d entries, want 2", len(list.Tasks))
462		}
463		first := list.Tasks[0]
464		if first.Status != "in_progress" || first.Attempts != 1 || first.CompletedAt != nil || len(first.Result) != 0 {
465			t.Fatalf("list task 1 = %+v", first)
466		}
467		if first.ClaimedAt == nil || !first.ClaimedAt.Equal(*claimedAt) ||
468			first.Deadline == nil || !first.Deadline.Equal(deadline) {
469			t.Fatalf("list task 1 lost claim times: %+v", first)
470		}
471		if list.Tasks[1].Status != "pending" {
472			t.Fatalf("list task 2 = %+v, want pending", list.Tasks[1])
473		}
474	}
475	
476	// Once storage recovers within the original deadline, re-issuing the cancel
477	// returns 200 and fully cancels: the completion time is the successful cancel's
478	// server time, attempts are unchanged, the claim times disappear and exactly
479	// one canceled audit record is appended while the earlier records keep their
480	// order and content. The released device then claims the previously blocked
481	// task; the canceled task can no longer be claimed and a report on its now
482	// invalid credential is 409, saving no result, receipt or audit record.
483	func TestPersistentTaskCancelWriteFailureRecoversAndCancels(t *testing.T) {
484		dir := t.TempDir()
485		store := openPersistent(t, dir)
486		clock := time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC)
487		store.now = func() time.Time { return clock }
488		h := NewHandler(store)
489		mustRegister(t, h, "gw")
490	
491		createTask(t, h, "gw", taskBody("req-1", 30), http.StatusCreated)
492		claim := claimTask(t, h, "gw", http.StatusOK)
493		createTask(t, h, "gw", taskBody("req-2", 30), http.StatusCreated)
494		beforeAudit := listAudit(t, h, "gw", 1)
495	
496		// Failed cancel: 503, execution preserved.
497		real := store.wal.(*walFile)
498		store.wal = &failingWAL{inner: real}
499		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/tasks/1/cancel", ""); r.Code != http.StatusServiceUnavailable {
500			t.Fatalf("failing cancel = %d, want 503: %s", r.Code, r.Body.String())
501		}
502	
503		// Storage recovers while the original deadline is still open.
504		clock = clock.Add(5 * time.Second)
505		store.wal = real
506		canceled := cancelTask(t, h, "gw", 1, http.StatusOK)
507		if canceled.Status != "canceled" {
508			t.Fatalf("retried cancel status = %q, want canceled", canceled.Status)
509		}
510		if canceled.Attempts != 1 {
511			t.Fatalf("cancel changed attempts to %d, want 1", canceled.Attempts)
512		}
513		if canceled.CompletedAt == nil || !canceled.CompletedAt.Equal(clock) {
514			t.Fatalf("cancel completedAt = %+v, want success time %s", canceled.CompletedAt, clock)
515		}
516		if canceled.ClaimedAt != nil || canceled.Deadline != nil {
517			t.Fatalf("canceled view still carries claim times: %+v", canceled)
518		}
519	
520		// The query view agrees; the old claim time and deadline are gone.
521		task := getTask(t, h, "gw", 1, http.StatusOK)
522		if task.Status != "canceled" || task.Attempts != 1 || task.ClaimedAt != nil || task.Deadline != nil {
523			t.Fatalf("task after recovered cancel: %+v", task)
524		}
525		if task.CompletedAt == nil || !task.CompletedAt.Equal(clock) || len(task.Result) != 0 {
526			t.Fatalf("task outcome after recovered cancel: %+v", task)
527		}
528	
529		// Exactly one canceled audit record follows the unchanged earlier records.
530		audit := listAudit(t, h, "gw", 1)
531		if len(audit) != 3 {
532			t.Fatalf("audit len = %d, want 3: %+v", len(audit), audit)
533		}
534		if audit[0] != beforeAudit[0] || audit[1] != beforeAudit[1] {
535			t.Fatalf("cancel reordered/changed earlier audit: %+v vs %+v", audit[:2], beforeAudit)
536		}
537		cancelRec := audit[2]
538		if cancelRec.Event != "canceled" || cancelRec.FromStatus != "in_progress" ||
539			cancelRec.ToStatus != "canceled" || !cancelRec.At.Equal(clock) {
540			t.Fatalf("cancel audit record = %+v", cancelRec)
541		}
542	
543		// The released device claims the task the failed cancel had blocked; the
544		// canceled task is not offered.
545		claim2 := claimTask(t, h, "gw", http.StatusOK)
546		if claim2.Task.ID != 2 {
547			t.Fatalf("claim after cancel took task %d, want 2", claim2.Task.ID)
548		}
549		claimTask(t, h, "gw", http.StatusNoContent)
550	
551		// A report on the canceled task with its old credential is 409 and saves
552		// nothing: no result, no receipt binding and no new audit record.
553		reportTask(t, h, "gw", 1,
554			reportBody("rcpt-blocked", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
555		task = getTask(t, h, "gw", 1, http.StatusOK)
556		if task.Status != "canceled" || len(task.Result) != 0 || !task.CompletedAt.Equal(clock) {
557			t.Fatalf("conflicting report disturbed the canceled task: %+v", task)
558		}
559		ts1 := store.devices["gw"].tasks[0]
560		if len(ts1.reports) != 0 {
561			t.Fatalf("conflicting report saved a receipt: %+v", ts1.reports)
562		}
563		if _, bound := store.devices["gw"].taskReceipts["rcpt-blocked"]; bound {
564			t.Fatalf("conflicting report bound the receipt number to task 1")
565		}
566		if len(listAudit(t, h, "gw", 1)) != 3 {
567			t.Fatalf("conflicting report added an audit record")
568		}
569	
570		// The rejected number was not occupied: task 2 accepts it on its own claim.
571		reportTask(t, h, "gw", 2,
572			reportBody("rcpt-blocked", claim2.Credential, true, "", `{"ok":true}`), http.StatusCreated)
573		// Nothing claimable remains: the canceled task must never be claimed.
574		claimTask(t, h, "gw", http.StatusNoContent)
575	}
576	
577	// A cancel that could not be persisted must not have revoked the execution
578	// credential. With storage healthy again and the deadline still open, the
579	// device reports success against the original claim: 201, the result is saved
580	// and the task ends as succeeded with no canceled audit record. This is the
581	// deliberate counterpart of the post-cancel 409 above: only a successfully
582	// persisted cancel invalidates the credential; the earlier 503 does not.
583	func TestPersistentTaskFailedCancelKeepsCredentialForSuccessReport(t *testing.T) {
584		dir := t.TempDir()
585		store := openPersistent(t, dir)
586		clock := time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC)
587		store.now = func() time.Time { return clock }
588		h := NewHandler(store)
589		mustRegister(t, h, "gw")
590	
591		createTask(t, h, "gw", taskBody("req-1", 30), http.StatusCreated)
592		createTask(t, h, "gw", taskBody("req-2", 30), http.StatusCreated)
593		claim := claimTask(t, h, "gw", http.StatusOK) // task 1
594	
595		// The cancel write fails: 503, the execution is untouched.
596		real := store.wal.(*walFile)
597		store.wal = &failingWAL{inner: real}
598		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/tasks/1/cancel", ""); r.Code != http.StatusServiceUnavailable {
599			t.Fatalf("failing cancel = %d, want 503: %s", r.Code, r.Body.String())
600		}
601	
602		// Storage recovers while the original deadline is still open.
603		clock = clock.Add(5 * time.Second)
604		store.wal = real
605	
606		// The original claim still authorizes the success report (not a 409).
607		report := reportTask(t, h, "gw", 1,
608			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusCreated)
609		if !report.Success || !report.ReceivedAt.Equal(clock) {
610			t.Fatalf("report after failed cancel = %+v", report)
611		}
612		task := getTask(t, h, "gw", 1, http.StatusOK)
613		if task.Status != "succeeded" || task.CompletedAt == nil || !task.CompletedAt.Equal(clock) {
614			t.Fatalf("task after late success report: %+v", task)
615		}
616		if string(task.Result) != `{"ok":true}` {
617			t.Fatalf("saved result = %s, want {\"ok\":true}", task.Result)
618		}
619		if task.ClaimedAt != nil || task.Deadline != nil || task.Attempts != 1 {
620			t.Fatalf("success report changed claim fields: %+v", task)
621		}
622		// No canceled record was ever committed by the failed attempt.
623		if got := joinEvents(eventsOf(listAudit(t, h, "gw", 1))); got != "created,claimed,succeeded" {
624			t.Fatalf("audit = %s, want created,claimed,succeeded", got)
625		}
626	
627		// The success released the device, so the previously blocked task advances.
628		claim2 := claimTask(t, h, "gw", http.StatusOK)
629		if claim2.Task.ID != 2 {
630			t.Fatalf("claim after success took task %d, want 2", claim2.Task.ID)
631		}
632	
633		// Restart proves the failed cancel left no durable trace: the task is
634		// recovered as succeeded with the same result and audit trail.
635		if err := store.Close(); err != nil {
636			t.Fatal(err)
637		}
638		store2 := reopenPersistent(t, dir)
639		h2 := NewHandler(store2)
640		task = getTask(t, h2, "gw", 1, http.StatusOK)
641		if task.Status != "succeeded" || string(task.Result) != `{"ok":true}` || task.CompletedAt == nil {
642			t.Fatalf("task after restart = %+v", task)
643		}
644		if got := joinEvents(eventsOf(listAudit(t, h2, "gw", 1))); got != "created,claimed,succeeded" {
645			t.Fatalf("audit after restart = %s, want created,claimed,succeeded", got)
646		}
647	}
648	
649	// permanentFailingWAL always fails to append, leaving in-memory state untouched.
650	type permanentFailingWAL struct{}
651	
652	func (w *permanentFailingWAL) appendRecord(recType byte, value any) error {
653		return fmt.Errorf("simulated permanent disk failure")
654	}
655	
656	// --- an old data directory (pre-task records) still opens --------------------
657	
658	func TestPersistentOldDataDirStillOpens(t *testing.T) {
659		dir := t.TempDir()
660		store := openPersistent(t, dir)
661		h := NewHandler(store)
662		mustRegister(t, h, "gw")
663		// Write only pre-task records.
664		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
665		if err := store.Close(); err != nil {
666			t.Fatal(err)
667		}
668	
669		// Reopen with the new code: the old records recover and tasks work fresh.
670		store2 := reopenPersistent(t, dir)
671		h2 := NewHandler(store2)
672		status := getConfigStatus(t, h2, "gw")
673		if status.TargetVersion != 1 {
674			t.Fatalf("old config after restart = %+v", status)
675		}
676		createTask(t, h2, "gw", taskBody("req-1", 30), http.StatusCreated)
677		list := decodeBody[struct {
678			Tasks []taskResponse `json:"tasks"`
679		}](t, doRequest(t, h2, http.MethodGet, "/v1/devices/gw/tasks", ""))
680		if len(list.Tasks) != 1 || list.Tasks[0].Status != "pending" {
681			t.Fatalf("tasks on old data dir = %+v", list.Tasks)
682		}
683	}
